CREATE TYPE "Role" AS ENUM ('TRABAJADOR', 'CONDUCTOR');
CREATE TYPE "RequestStatus" AS ENUM ('PENDIENTE', 'ACEPTADA', 'EN_CURSO', 'FINALIZADA', 'RECHAZADA');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "WorkerProfile" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE,"bio" TEXT,"phone" TEXT,CONSTRAINT "WorkerProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Service" ("id" TEXT PRIMARY KEY,"workerId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"price" DECIMAL(10,2) NOT NULL,"zone" TEXT NOT NULL,"safePoint" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Service_workerId_fkey" FOREIGN KEY ("workerId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "ServiceRequest" ("id" TEXT PRIMARY KEY,"serviceId" TEXT NOT NULL,"driverId" TEXT NOT NULL,"workerId" TEXT NOT NULL,"scheduledAt" TIMESTAMP(3) NOT NULL,"status" "RequestStatus" NOT NULL DEFAULT 'PENDIENTE',"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ServiceRequest_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE RESTRICT,CONSTRAINT "ServiceRequest_driverId_fkey" FOREIGN KEY ("driverId") REFERENCES "User"("id") ON DELETE RESTRICT,CONSTRAINT "ServiceRequest_workerId_fkey" FOREIGN KEY ("workerId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY,"requestId" TEXT NOT NULL UNIQUE,"amount" DECIMAL(10,2) NOT NULL,"paidAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Payment_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ServiceRequest"("id") ON DELETE RESTRICT);
CREATE INDEX "Service_zone_active_idx" ON "Service"("zone","active");
CREATE INDEX "ServiceRequest_workerId_scheduledAt_idx" ON "ServiceRequest"("workerId","scheduledAt");
CREATE INDEX "ServiceRequest_driverId_idx" ON "ServiceRequest"("driverId");
